// Regex-based XML parser (Browser/Node compatible)
function extractTitles(xml, count = 5) {
    const items = xml.match(/<item>([\s\S]*?)<\/item>/g) || [];
    return items.slice(0, count).map(item => {
        const titleMatch = item.match(/<title>([\s\S]*?)<\/title>/);
        return titleMatch ? titleMatch[1].replace(/<!\[CDATA\[(.*?)\]\]>/, '$1') : null;
    }).filter(t => t);
}

// Delay helper to be polite to the proxy
const delay = (ms) => new Promise(res => setTimeout(res, ms));

async function fetchFeed(term) {
    const targetUrl = `https://news.google.com/rss/search?q=${encodeURIComponent(term)}`;
    const proxyUrl = `https://corsproxy.io/?${encodeURIComponent(targetUrl)}`;

    try {
        const res = await fetch(proxyUrl);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const text = await res.text();
        return { term, titles: extractTitles(text) };
    } catch (e) {
        return { term, error: e.message };
    }
}

console.log("=== 🌍 GLOBAL CONTEXT BUFFER ===");

for (const term of feeds) {
    const result = await fetchFeed(term);

    console.log(`📡 ${result.term}:`);
    if (result.error) {
        console.log(`  (Signal Lost: ${result.error})`);
    } else {
        result.titles.forEach(t => console.log(`  - ${t}`));
    }

    await delay(200);
}

